// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"errors"
	"fmt"
	"time"

	_ "modernc.org/sqlite"
)

// ErrInstanceNotFound reports that a targeted instance does not exist.
var ErrInstanceNotFound = errors.New("instance not found")

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Instance is the current record of one registered service instance.
type Instance struct {
	ServiceName string
	InstanceID  string
	Address     string
	Port        int64
	Healthy     bool
	Weight      float64
	HeartbeatAt time.Time
}

// InstanceInput carries the fields callers provide on registration or update.
type InstanceInput struct {
	ServiceName string
	InstanceID  string
	Address     string
	Port        int64
	Healthy     bool
	Weight      float64
	HeartbeatAt time.Time
}

// HeartbeatTarget carries one heartbeat renewal in a batch: the existing
// instance identified by InstanceID gets only its HeartbeatAt replaced.
type HeartbeatTarget struct {
	InstanceID  string
	HeartbeatAt time.Time
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	if err := migrate(db); err != nil {
		db.Close()
		return nil, fmt.Errorf("migrate schema: %w", err)
	}
	return &Store{db: db}, nil
}

// migrate upgrades database files created by earlier versions in place.
func migrate(db *sql.DB) error {
	var count int
	if err := db.QueryRow(
		`SELECT COUNT(1) FROM pragma_table_info('service_instances') WHERE name = 'port'`).Scan(&count); err != nil {
		return err
	}
	if count == 0 {
		if _, err := db.Exec(`ALTER TABLE service_instances ADD COLUMN port INTEGER NOT NULL DEFAULT 0`); err != nil {
			return err
		}
	}
	return nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// UpsertInstance inserts an instance record or overwrites the current record
// of the same (service name, instance id) pair.
func (s *Store) UpsertInstance(input InstanceInput) (Instance, error) {
	heartbeat := input.HeartbeatAt.UTC().Format(time.RFC3339Nano)
	_, err := s.db.Exec(`
INSERT INTO service_instances
	(service_name, instance_id, address, port, healthy, weight, heartbeat_at)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(service_name, instance_id) DO UPDATE SET
	address = excluded.address,
	port = excluded.port,
	healthy = excluded.healthy,
	weight = excluded.weight,
	heartbeat_at = excluded.heartbeat_at`,
		input.ServiceName, input.InstanceID, input.Address, input.Port, input.Healthy, input.Weight, heartbeat)
	if err != nil {
		return Instance{}, err
	}
	return Instance{
		ServiceName: input.ServiceName,
		InstanceID:  input.InstanceID,
		Address:     input.Address,
		Port:        input.Port,
		Healthy:     input.Healthy,
		Weight:      input.Weight,
		HeartbeatAt: input.HeartbeatAt.UTC(),
	}, nil
}

// UpsertInstances inserts or overwrites several instances of one service in a
// single transaction. Every input shares the same service name and instance
// ids are expected to be unique within the batch; stored records are returned
// in request order. Any failure rolls the whole batch back without leaving
// partial updates.
func (s *Store) UpsertInstances(inputs []InstanceInput) ([]Instance, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()

	statement, err := tx.Prepare(`
INSERT INTO service_instances
	(service_name, instance_id, address, port, healthy, weight, heartbeat_at)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(service_name, instance_id) DO UPDATE SET
	address = excluded.address,
	port = excluded.port,
	healthy = excluded.healthy,
	weight = excluded.weight,
	heartbeat_at = excluded.heartbeat_at`)
	if err != nil {
		return nil, err
	}
	defer statement.Close()

	for _, input := range inputs {
		if _, err := statement.Exec(
			input.ServiceName, input.InstanceID, input.Address, input.Port,
			input.Healthy, input.Weight,
			input.HeartbeatAt.UTC().Format(time.RFC3339Nano)); err != nil {
			return nil, err
		}
	}

	instances := make([]Instance, 0, len(inputs))
	for _, input := range inputs {
		instances = append(instances, Instance{
			ServiceName: input.ServiceName,
			InstanceID:  input.InstanceID,
			Address:     input.Address,
			Port:        input.Port,
			Healthy:     input.Healthy,
			Weight:      input.Weight,
			HeartbeatAt: input.HeartbeatAt.UTC(),
		})
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return instances, nil
}

// GetInstance reads the current record of one instance.
func (s *Store) GetInstance(serviceName, instanceID string) (Instance, bool, error) {
	row := s.db.QueryRow(`
SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
FROM service_instances
WHERE service_name = ? AND instance_id = ?`, serviceName, instanceID)
	instance, err := scanInstance(row)
	if err == sql.ErrNoRows {
		return Instance{}, false, nil
	}
	if err != nil {
		return Instance{}, false, err
	}
	return instance, true, nil
}

// ListInstances reads every current record belonging to one service. Other
// services are never touched or removed.
func (s *Store) ListInstances(serviceName string) ([]Instance, error) {
	rows, err := s.db.Query(`
SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
FROM service_instances
WHERE service_name = ?`, serviceName)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	instances := make([]Instance, 0)
	for rows.Next() {
		instance, err := scanInstance(rows)
		if err != nil {
			return nil, err
		}
		instances = append(instances, instance)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return instances, nil
}

// ListAllInstances reads every current record across all services. It never
// creates, updates or deletes rows; callers aggregate the read-only snapshot
// themselves. Results are ordered by service name and then instance id so
// identical storage content yields identical output.
func (s *Store) ListAllInstances() ([]Instance, error) {
	rows, err := s.db.Query(`
SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
FROM service_instances
ORDER BY service_name ASC, instance_id ASC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	instances := make([]Instance, 0)
	for rows.Next() {
		instance, err := scanInstance(rows)
		if err != nil {
			return nil, err
		}
		instances = append(instances, instance)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return instances, nil
}

// DeleteInstance removes one instance record and reports whether it existed.
func (s *Store) DeleteInstance(serviceName, instanceID string) (bool, error) {
	result, err := s.db.Exec(`
DELETE FROM service_instances WHERE service_name = ? AND instance_id = ?`, serviceName, instanceID)
	if err != nil {
		return false, err
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return false, err
	}
	return affected > 0, nil
}

// InstanceKey identifies one instance record for a targeted write.
type InstanceKey struct {
	ServiceName string
	InstanceID  string
}

// DeleteInstances removes the identified records in a single transaction.
// Any failure rolls the whole batch back, so a failed request never leaves
// partial deletions behind.
func (s *Store) DeleteInstances(keys []InstanceKey) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	statement, err := tx.Prepare(`
DELETE FROM service_instances WHERE service_name = ? AND instance_id = ?`)
	if err != nil {
		return err
	}
	defer statement.Close()

	for _, key := range keys {
		if _, err := statement.Exec(key.ServiceName, key.InstanceID); err != nil {
			return err
		}
	}
	return tx.Commit()
}

// TouchHeartbeats replaces only heartbeat_at of the named service's
// instances. The whole batch runs in one transaction: when any target does
// not exist the transaction rolls back and ErrInstanceNotFound is returned
// without partial updates. Updated records are returned in request order.
func (s *Store) TouchHeartbeats(serviceName string, targets []HeartbeatTarget) ([]Instance, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer tx.Rollback()

	statement, err := tx.Prepare(`
UPDATE service_instances SET heartbeat_at = ?
WHERE service_name = ? AND instance_id = ?`)
	if err != nil {
		return nil, err
	}
	defer statement.Close()

	for _, target := range targets {
		result, err := statement.Exec(
			target.HeartbeatAt.UTC().Format(time.RFC3339Nano), serviceName, target.InstanceID)
		if err != nil {
			return nil, err
		}
		affected, err := result.RowsAffected()
		if err != nil {
			return nil, err
		}
		if affected == 0 {
			return nil, ErrInstanceNotFound
		}
	}

	updated := make([]Instance, 0, len(targets))
	for _, target := range targets {
		row := tx.QueryRow(`
SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
FROM service_instances
WHERE service_name = ? AND instance_id = ?`, serviceName, target.InstanceID)
		instance, err := scanInstance(row)
		if err == sql.ErrNoRows {
			return nil, ErrInstanceNotFound
		}
		if err != nil {
			return nil, err
		}
		updated = append(updated, instance)
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return updated, nil
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanInstance(scanner rowScanner) (Instance, error) {
	var instance Instance
	var healthy int
	var heartbeat string
	if err := scanner.Scan(&instance.ServiceName, &instance.InstanceID, &instance.Address,
		&instance.Port, &healthy, &instance.Weight, &heartbeat); err != nil {
		return Instance{}, err
	}
	parsed, err := time.Parse(time.RFC3339Nano, heartbeat)
	if err != nil {
		return Instance{}, err
	}
	instance.Healthy = healthy != 0
	instance.HeartbeatAt = parsed
	return instance, nil
}

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS service_instances (
	service_name TEXT NOT NULL,
	instance_id  TEXT NOT NULL,
	address      TEXT NOT NULL DEFAULT '',
	port         INTEGER NOT NULL DEFAULT 0,
	healthy      INTEGER NOT NULL DEFAULT 0,
	weight       REAL NOT NULL DEFAULT 0,
	heartbeat_at TEXT NOT NULL,
	PRIMARY KEY(service_name, instance_id)
);
`
package api

import (
	"bytes"
	"encoding/json"
	"io"
	"math"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

// Parameter names accepted on every entry point. The first name of each list
// is the canonical name used in responses.
var (
	serviceNameKeys = []string{"service_name", "serviceName", "service"}
	instanceIDKeys  = []string{"instance_id", "instanceId", "instance", "id"}
	addressKeys     = []string{"address", "addr", "host", "endpoint"}
	portKeys        = []string{"port"}
	healthKeys      = []string{"health", "healthy", "status", "state"}
	weightKeys      = []string{"weight"}
	heartbeatKeys   = []string{"heartbeat_at", "heartbeatAt", "heartbeat", "heartbeat_time", "heartbeatTime", "last_heartbeat"}
	evaluateAtKeys  = []string{"evaluate_at", "evaluateAt", "at", "now", "evaluate_time", "evaluateTime"}
	timeoutKeys     = []string{"heartbeat_timeout", "heartbeatTimeout", "timeout", "timeout_seconds", "timeoutSeconds", "heartbeat_timeout_seconds"}
)

type apiError struct {
	status  int
	code    string
	message string
}

func errInvalidParameter(message string) *apiError {
	return &apiError{http.StatusBadRequest, "invalid_parameter", message}
}

func errInstanceNotFound() *apiError {
	return &apiError{http.StatusNotFound, "instance_not_found", "service instance not found"}
}

func errStorageUnavailable() *apiError {
	return &apiError{http.StatusServiceUnavailable, "storage_unavailable", "database is not available"}
}

func writeError(c *gin.Context, e *apiError) {
	c.JSON(e.status, gin.H{"error": gin.H{"code": e.code, "message": e.message}})
}

// paramBag merges path parameters, JSON body fields and query parameters.
// Explicit path parameters win, then body fields, then query parameters.
type paramBag struct {
	values map[string]any
}

func buildParamBag(c *gin.Context) (*paramBag, *apiError) {
	bag := &paramBag{values: make(map[string]any)}

	for key, values := range c.Request.URL.Query() {
		if len(values) > 0 {
			bag.values[key] = values[0]
		}
	}

	if c.Request.Body != nil {
		raw, err := io.ReadAll(c.Request.Body)
		if err != nil {
			return nil, errInvalidParameter("request body cannot be read")
		}
		if len(bytes.TrimSpace(raw)) > 0 {
			var body map[string]any
			if err := json.Unmarshal(raw, &body); err != nil {
				return nil, errInvalidParameter("request body must be a JSON object")
			}
			for key, value := range body {
				bag.values[key] = value
			}
		}
	}

	for _, param := range c.Params {
		bag.values[param.Key] = param.Value
	}
	return bag, nil
}

func (b *paramBag) get(keys []string) (any, bool) {
	for _, key := range keys {
		if value, ok := b.values[key]; ok {
			return value, true
		}
	}
	return nil, false
}

func stringValue(value any) string {
	if text, ok := value.(string); ok {
		return text
	}
	return ""
}

// requiredText returns the trimmed text for the first matching key, or an error
// when the value is missing or blank.
func (b *paramBag) requiredText(keys []string, message string) (string, *apiError) {
	value, ok := b.get(keys)
	if !ok {
		return "", errInvalidParameter(message)
	}
	text := strings.TrimSpace(stringValue(value))
	if text == "" {
		return "", errInvalidParameter(message)
	}
	return text, nil
}

// positiveNumber accepts weights: only numbers strictly greater than zero.
func positiveNumber(value any) (float64, bool) {
	number, ok := toFloat(value)
	if !ok || math.IsNaN(number) || math.IsInf(number, 0) || number <= 0 {
		return 0, false
	}
	return number, true
}

// parsePortValue accepts a non-negative integer port number.
func parsePortValue(value any) (int64, bool) {
	number, ok := toFloat(value)
	if !ok || math.IsNaN(number) || math.IsInf(number, 0) || number < 0 ||
		number != math.Trunc(number) || number > math.MaxInt64 {
		return 0, false
	}
	return int64(number), true
}

// strictBoolValue accepts only JSON boolean true or false. Every other
// representation (text, numbers) is rejected so all implementations agree.
func strictBoolValue(value any) (bool, bool) {
	typed, ok := value.(bool)
	return typed, ok
}

func toFloat(value any) (float64, bool) {
	switch typed := value.(type) {
	case float64:
		return typed, true
	case int:
		return float64(typed), true
	case int64:
		return float64(typed), true
	case json.Number:
		number, err := typed.Float64()
		if err != nil {
			return 0, false
		}
		return number, true
	case string:
		number, err := strconv.ParseFloat(strings.TrimSpace(typed), 64)
		if err != nil {
			return 0, false
		}
		return number, true
	default:
		return 0, false
	}
}

func parseHealthValue(value any) (bool, bool) {
	switch typed := value.(type) {
	case bool:
		return typed, true
	case float64:
		switch typed {
		case 1:
			return true, true
		case 0:
			return false, true
		}
	case string:
		switch strings.ToLower(strings.TrimSpace(typed)) {
		case "healthy", "up", "on", "true", "1", "yes":
			return true, true
		case "unhealthy", "down", "off", "false", "0", "no":
			return false, true
		}
	}
	return false, false
}

func parseTimeValue(value any) (time.Time, bool) {
	switch typed := value.(type) {
	case string:
		text := strings.TrimSpace(typed)
		if text == "" {
			return time.Time{}, false
		}
		if number, err := strconv.ParseFloat(text, 64); err == nil {
			return unixTime(number), true
		}
		for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05"} {
			if parsed, err := time.Parse(layout, text); err == nil {
				return parsed, true
			}
		}
	case float64:
		return unixTime(typed), true
	}
	return time.Time{}, false
}

func unixTime(seconds float64) time.Time {
	whole := int64(seconds)
	fraction := seconds - float64(whole)
	return time.Unix(whole, int64(fraction*1e9)).UTC()
}

// parseTimeout accepts a number of seconds or a duration string such as "30s".
// A non-positive duration is reported as invalid by the caller.
func parseTimeout(value any) (time.Duration, bool) {
	switch typed := value.(type) {
	case float64:
		if math.IsNaN(typed) || math.IsInf(typed, 0) {
			return 0, false
		}
		return time.Duration(typed * float64(time.Second)), true
	case string:
		text := strings.TrimSpace(typed)
		if text == "" {
			return 0, false
		}
		if duration, err := time.ParseDuration(text); err == nil {
			return duration, true
		}
		if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
			return time.Duration(number * float64(time.Second)), true
		}
	}
	return 0, false
}

