	c.JSON(200, gin.H{
		"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
		"heartbeat_timeout": jsonWeight(timeout.Seconds()),
		"removed":           len(removed),
		"instances":         removed,
	})
